query GeneGroupTables($FBgg: String!) {
  geneGroupv2(id: $FBgg) {
    id
    type
    subgroups: geneGroupv2sByGeneGroupMemberv2GeneGroupIdAndSubgroupIdList {
      id
      name
      nameSgml
      symbol
      symbolSgml
      memberships: geneGroupMemberv2sBySubgroupId(condition: {geneGroupId: $FBgg}) {
        ...GeneGroupMember
        __typename
      }
      __typename
    }
    memberships: geneGroupMemberv2sByGeneGroupId(condition: {subgroupId: null}) {
      ...GeneGroupMember
      __typename
    }
    __typename
  }
}

fragment GeneGroupMember on GeneGroupMemberv2 {
  geneGroupPubs
  gene {
    id
    symbol
    symbolSgml
    name
    nameSgml
    aka
    pubs
    antibody
    transgenicConstructs: geneAllelev2sByGeneId(condition: {isConstruct: true}) {
      allele {
        id
        symbol
        __typename
      }
      __typename
    }
    classicalAndInsertionAlleles: geneAllelev2sByGeneId(
      condition: {isConstruct: false}
    ) {
      allele {
        id
        symbol
        __typename
      }
      __typename
    }
    geneGroups: geneGroupMemberv2sByGeneId(condition: {subgroupId: null}) {
      geneGroup {
        id
        symbol
        name
        type
        __typename
      }
      __typename
    }
    experimentalDiseaseModels: geneDiseasev2sByGeneId(
      condition: {isExperimental: true}
    ) {
      disease {
        id
        name
        __typename
      }
      __typename
    }
    potentialDiseaseModels: geneDiseasev2sByGeneId(
      condition: {isExperimental: false}
    ) {
      disease {
        id
        name
        __typename
      }
      __typename
    }
    humanOrthologs: geneHumanOrthologv2sByGeneId {
      dioptScore
      name
      url
      ortholog {
        id
        symbol
        organismId
        __typename
      }
      __typename
    }
    testisSpecificityIndex
    enzymes: enzymev2sByGeneEnzymev2GeneIdAndEnzymeIdList {
      id
      name
      __typename
    }
    experimentalGoMolecularFunctions: geneGoMolecularFunctionv2sByGeneId(
      condition: {isExperimental: true}
    ) {
      goId
      goMolecularFunction
      __typename
    }
    nonExperimentalGoMolecularFunctions: geneGoMolecularFunctionv2sByGeneId(
      condition: {isExperimental: false}
    ) {
      goId
      goMolecularFunction
      __typename
    }
    cytogenicMap
    __typename
  }
  __typename
}
query GeneToolKitMostCommonlyUsed($geneId: String) {
  classicalAndInsertionsAlleles: genes(condition: {id: $geneId}) {
    alleles(condition: {isConstruct: false, geneIsRegulatoryRegion: false}) {
      id
      paperCount
      stocksCount
      pubCount
      symbol
      classes {
        name
        __typename
      }
      tagUses {
        name
        __typename
      }
      __typename
    }
    __typename
  }
  transgenicConstructs: genes(condition: {id: $geneId}) {
    alleles(condition: {isConstruct: true, geneIsRegulatoryRegion: false}) {
      id
      paperCount
      stocksCount
      pubCount
      symbol
      transgenicProductClasses {
        transgenicProductClass
        __typename
      }
      classes {
        name
        __typename
      }
      regRegions {
        symbol
        __typename
      }
      taggedWith {
        symbol
        __typename
      }
      tagUses {
        name
        __typename
      }
      __typename
    }
    __typename
  }
}
